WITH v AS (SELECT o.customer_id, o.order_at FROM orders o WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed')), f AS (SELECT customer_id, MIN(order_at) AS first_at FROM v GROUP BY 1) SELECT COUNT(*) AS cohort, SUM(CASE WHEN EXISTS (SELECT 1 FROM v WHERE v.customer_id = f.customer_id AND CAST(v.order_at AS DATE) BETWEEN DATE '2025-04-01' AND DATE '2025-06-30') THEN 1 ELSE 0 END) AS retained FROM f WHERE CAST(f.first_at AS DATE) BETWEEN DATE '2025-01-01' AND DATE '2025-03-31'
